buggy.described_examples:
import mpmath as mp

# Test 1: formatting mp.mpf('0.1') with format spec '.016f'
try:
    result1 = format(mp.mpf('0.1'), '.016f')
    probe("@example(fmt='.016f', x=0.1) added to mpmath/tests/test_format.py::test_mpf_fmt_cpython", result1)
except Exception as e:
    probe_exception("@example(fmt='.016f', x=0.1) added to mpmath/tests/test_format.py::test_mpf_fmt_cpython", e)

# Test 2: formatting mp.mpf('0.3') with format spec '0030f'
try:
    result2 = format(mp.mpf('0.3'), '0030f')
    probe("@example(fmt='0030f', x=0.3) added to mpmath/tests/test_format.py::test_mpf_fmt_cpython", result2)
except Exception as e:
    probe_exception("@example(fmt='0030f', x=0.3) added to mpmath/tests/test_format.py::test_mpf_fmt_cpython", e)

# Test 3: round(mp.mpf('inf')) should raise OverflowError
try:
    result3 = round(mp.mpf('inf'))
    probe("round(mp.mpf('inf')) / int(mp.inf)", result3)
except OverflowError as e:
    probe_exception("round(mp.mpf('inf')) / int(mp.inf)", e)
except Exception as e:
    probe_exception("round(mp.mpf('inf')) / int(mp.inf)", e)

